<script setup lang="ts">
import {pageFriendlyMapScroll} from '../runtime/mapScroll'
let disposeMapScroll:(()=>void)|undefined

import CustomerAppNav from './CustomerAppNav.vue'
import {computed,nextTick,onBeforeUnmount,onMounted,ref} from 'vue'
import {RouterLink} from 'vue-router'
import {useApp} from '../stores/app'
import {loadKakao} from '../services/kakao'
import TrafficVideo from './TrafficVideo.vue'
import {getNearbyBusanCctvs} from '../services/busanCctv'
import {navigationRequest,searchNavigationPlaces,routePoints,passesAvoidPoint,type Place,type Route,type Point,type Guide} from '../services/navigation'
import '../styles/customer-app-7.css'
import '../styles/customer-directions.css'
const store=useApp(),mapHost=ref<HTMLElement>(),originText=ref('부산역'),destinationText=ref('서면역'),origin=ref<Place|null>(null),destination=ref<Place|null>(null),choices=ref<Place[]>([]),choosing=ref<'origin'|'destination'>('origin')
const routes=ref<Route[]>([]),selected=ref(0),busy=ref(false),error=ref(''),mapError=ref(''),avoid=ref<Point|null>(null),pickingAvoid=ref(false)
type Weather={temperature:number|null;humidity:number|null;rainfall:number|null;condition:string;observedAt:string}
type Camera={name:string;url:string}
const weather=ref<Weather|null>(null),weatherError=ref(''),cameras=ref<Camera[]>([]),cameraError=ref(''),infoLoading=ref(false),camera=ref<Camera|null>(null),videoError=ref(false)
const active=computed(()=>routes.value[selected.value]),guides=computed(()=>active.value?.sections.flatMap(section=>section.guides||[])||[])
let sdk:any,map:any,resize:ResizeObserver|undefined,drawn:any[]=[],avoidCircle:any,controller:AbortController|undefined,alive=true
const events:{event:string;handler:(...args:any[])=>void}[]=[],coord=(point:Point)=>`${point.lng},${point.lat}`
function listen(event:string,handler:(...args:any[])=>void){sdk.maps.event.addListener(map,event,handler);events.push({event,handler})}
function clearDrawing(){drawn.forEach(item=>item.setMap(null));drawn=[]}
function draw(){if(!map||!active.value||!origin.value||!destination.value)return;clearDrawing();const path=routePoints(active.value).map(p=>new sdk.maps.LatLng(p.lat,p.lng));if(!path.length)return;drawn.push(new sdk.maps.Polyline({map,path,strokeWeight:6,strokeColor:'#2878cc',strokeOpacity:.9}));for(const p of [origin.value,destination.value])drawn.push(new sdk.maps.Marker({map,position:new sdk.maps.LatLng(p.lat,p.lng),title:p.name}));const bounds=new sdk.maps.LatLngBounds();path.forEach(p=>bounds.extend(p));map.setBounds(bounds,40,40,40,40)}
function pickPlace(place:Place){if(choosing.value==='origin'){origin.value=place;originText.value=place.name}else{destination.value=place;destinationText.value=place.name}choices.value=[];routes.value=[];clearDrawing()}
async function searchPlace(field:'origin'|'destination'){choosing.value=field;error.value='';try{choices.value=await searchNavigationPlaces((field==='origin'?originText.value:destinationText.value).trim());if(!choices.value.length)error.value='검색한 장소를 찾지 못했습니다.'}catch(e){error.value=(e as Error).message}}
async function resolvePlace(field:'origin'|'destination',signal:AbortSignal){const existing=field==='origin'?origin.value:destination.value;if(existing)return existing;const q=(field==='origin'?originText.value:destinationText.value).trim();if(!q)throw Error('출발지와 도착지를 입력해 주세요.');const found=await searchNavigationPlaces(q,signal);if(!found.length)throw Error(`“${q}” 장소를 찾지 못했습니다.`);const place=found.find(p=>p.name===q)||found[0]!;if(field==='origin'){origin.value=place;originText.value=place.name}else{destination.value=place;destinationText.value=place.name}return place}
async function loadInfo(place:Place,signal:AbortSignal){infoLoading.value=true;weatherError.value='';cameraError.value='';const result=await Promise.allSettled([navigationRequest<Weather>('weather',{lat:String(place.lat),lng:String(place.lng)},signal),getNearbyBusanCctvs(place.lat,place.lng)]);if(!alive||signal.aborted)return;const [wx,cc]=result;if(wx.status==='fulfilled')weather.value=wx.value;else weatherError.value=wx.reason.message;if(cc.status==='fulfilled')cameras.value=cc.value;else cameraError.value=cc.reason.message;infoLoading.value=false}
async function search(){controller?.abort();const current=new AbortController();controller=current;busy.value=true;error.value='';routes.value=[];choices.value=[];weather.value=null;cameras.value=[];camera.value=null;clearDrawing();try{const [from,to]=await Promise.all([resolvePlace('origin',current.signal),resolvePlace('destination',current.signal)]);void loadInfo(to,current.signal);let candidates=await navigationRequest<Route[]>('directions',{origin:coord(from),destination:coord(to)},current.signal);if(avoid.value){const point=avoid.value;candidates=candidates.filter(r=>!passesAvoidPoint(r,point));if(!candidates.length){const dy=600/111000,dx=600/(111000*Math.cos(point.lat*Math.PI/180));for(const waypoint of [{lat:point.lat+dy,lng:point.lng},{lat:point.lat-dy,lng:point.lng},{lat:point.lat,lng:point.lng+dx},{lat:point.lat,lng:point.lng-dx}]){const found=await navigationRequest<Route[]>('directions',{origin:coord(from),destination:coord(to),waypoint:coord(waypoint)},current.signal);candidates.push(...found.filter(r=>!passesAvoidPoint(r,point)))}candidates.sort((a,b)=>a.summary.duration-b.summary.duration)}}if(!candidates.length)throw Error(avoid.value?'지정한 지점을 피하는 경로를 찾지 못했습니다.':'이 구간에서 자동차 경로를 찾지 못했습니다.');if(!alive||current.signal.aborted)return;routes.value=candidates;selected.value=0;await nextTick();draw()}catch(e){if(!current.signal.aborted)error.value=(e as Error).message}finally{if(!current.signal.aborted)busy.value=false}}
function clearAvoid(){avoid.value=null;avoidCircle?.setMap(null);pickingAvoid.value=false;routes.value=[];clearDrawing()}
function locate(){if(!navigator.geolocation){error.value='위치를 지원하지 않는 브라우저입니다.';return}navigator.geolocation.getCurrentPosition(p=>{if(!alive)return;origin.value={name:'내 위치',lat:p.coords.latitude,lng:p.coords.longitude};originText.value='내 위치';map?.panTo(new sdk.maps.LatLng(p.coords.latitude,p.coords.longitude))},()=>{if(alive)error.value='위치 권한을 확인해 주세요.'},{timeout:10000})}
function focusGuide(g:Guide){map?.setLevel(3);map?.panTo(new sdk.maps.LatLng(g.y,g.x))}
onMounted(async()=>{try{sdk=await loadKakao();if(!alive||!mapHost.value)return;map=new sdk.maps.Map(mapHost.value,{center:new sdk.maps.LatLng(35.1796,129.0756),level:7});disposeMapScroll=pageFriendlyMapScroll(mapHost.value,map);map.setCursor('grab');listen('dragstart',()=>map.setCursor('grabbing'));listen('dragend',()=>map.setCursor('grab'));listen('click',(e:any)=>{if(!pickingAvoid.value)return;avoid.value={lat:e.latLng.getLat(),lng:e.latLng.getLng()};avoidCircle?.setMap(null);avoidCircle=new sdk.maps.Circle({map,center:e.latLng,radius:150,strokeColor:'#c62828',strokeWeight:2,fillColor:'#c62828',fillOpacity:.15});pickingAvoid.value=false;routes.value=[];clearDrawing()});resize=new ResizeObserver(()=>{const center=map.getCenter();map.relayout();map.setCenter(center)});resize.observe(mapHost.value);draw()}catch(e){mapError.value=(e as Error).message}})
onBeforeUnmount(()=>{disposeMapScroll?.();alive=false;controller?.abort();resize?.disconnect();clearDrawing();avoidCircle?.setMap(null);events.forEach(({event,handler})=>sdk.maps.event.removeListener(map,event,handler))})
</script>
<template><div class="wire-page mobile-page page-customer-app-7"><div class="ph"><header class="ah"><span>길찾기</span><RouterLink class="app-bell" to="/customer-app/screen-12">알림</RouterLink><button type="button" class="theme-toggle" aria-label="라이트·다크 전환" @click="store.themeToggle()">◐</button></header><div class="bd directions-body"><form class="directions-form" @submit.prevent="search"><label>출발지<div><input :disabled="busy" v-model="originText" @input="origin=null" placeholder="출발 장소" required><button :disabled="busy" type="button" @click="searchPlace('origin')">검색</button><button :disabled="busy" type="button" @click="locate">내 위치</button></div></label><label>도착지<div><input :disabled="busy" v-model="destinationText" @input="destination=null" placeholder="도착 장소" required><button :disabled="busy" type="button" @click="searchPlace('destination')">검색</button></div></label><button class="btn p" :disabled="busy">{{busy?'경로 조회 중…':'길찾기'}}</button></form><ul v-if="choices.length" class="directions-place-results"><li v-for="place in choices" :key="place.id"><button @click="pickPlace(place)"><b>{{place.name}}</b><small>{{place.address}}</small></button></li></ul><p v-if="error" class="directions-error" role="alert">{{error}}</p><p v-if="mapError" role="alert">{{mapError}}</p><div class="directions-map-wrap"><div ref="mapHost" class="directions-map" aria-label="카카오 자동차 길찾기 지도"></div><div class="directions-map-zoom"><button aria-label="지도 확대" @click="map?.setLevel(Math.max(1,map.getLevel()-1))">+</button><button aria-label="지도 축소" @click="map?.setLevel(Math.min(14,map.getLevel()+1))">−</button></div></div><div class="directions-avoid"><button :aria-pressed="pickingAvoid" @click="pickingAvoid=!pickingAvoid">{{pickingAvoid?'지도에서 피할 지점을 누르세요':'회피 지점 지정'}}</button><button v-if="avoid" @click="clearAvoid">회피 지점 해제</button><small v-if="avoid">지정 지점 반경 150m를 피합니다. 길찾기를 다시 눌러 주세요.</small></div><p class="directions-source">경로: 카카오모빌리티 · 실제 침수·통제 정보는 연동 전입니다.</p><section v-if="routes.length" class="directions-results" aria-label="경로 결과"><h2>{{origin?.name}} → {{destination?.name}}</h2><button v-for="(route,index) in routes" :key="index" :aria-pressed="selected===index" @click="selected=index;draw()"><b>{{index===0?'추천':'대안'}} 경로 · {{Math.ceil(route.summary.duration/60)}}분</b><span>{{(route.summary.distance/1000).toFixed(1)}} km · 통행료 {{route.summary.fare?.toll?.toLocaleString()??'—'}}원</span></button><details><summary>구간별 안내 {{guides.length}}건</summary><ol><li v-for="(guide,index) in guides" :key="index"><button @click="focusGuide(guide)">{{guide.distance>0?guide.distance+'m 이동 후 ':''}}{{guide.guidance}} {{guide.name}}</button></li></ol></details></section><section v-if="destination&&(infoLoading||weather||weatherError||cameraError||cameras.length)" class="directions-local-info"><h2>도착지 인근 정보</h2><p v-if="infoLoading" role="status">날씨와 CCTV를 조회 중입니다.</p><p v-if="weatherError" role="status">{{weatherError}}</p><div v-if="weather" class="directions-weather"><b>{{weather.condition}} · {{weather.temperature??'—'}}°C</b><span>습도 {{weather.humidity??'—'}}% · 강우량 {{weather.rainfall??'—'}} mm</span><small>기상청 · {{new Date(weather.observedAt).toLocaleString('ko-KR')}}</small></div><h3>주변 도로 CCTV</h3><p v-if="cameraError" role="status">{{cameraError}}</p><p v-else-if="!infoLoading&&!cameras.length">부산시에서 제공하는 인근 CCTV가 없습니다.</p><p v-if="cameras.length" class="directions-source">주변 도로 영상이며 지하차도 내부 영상과 다를 수 있습니다.</p><ul class="directions-camera-list"><li v-for="item in cameras" :key="item.name+item.url"><button @click="camera=item;videoError=false">{{item.name}}</button></li></ul><div v-if="camera" class="directions-camera-player"><b>{{camera.name}}</b><TrafficVideo :src="camera.url" :hls="true"/><p v-if="videoError">이 브라우저에서 영상을 재생하지 못했습니다.</p><a :href="camera.url" target="_blank" rel="noopener noreferrer">영상 주소 열기 ↗</a></div></section></div><CustomerAppNav/></div></div></template>
